def get_unique_relic(world: "GrimDawnWorld") -> str:
    if len(world.local_relic_table) > 0:
        return world.local_relic_table.pop()
    else:
        return ""

def get_unique_gear(world: "GrimDawnWorld") -> str:
    if len(world.local_gear_table) > 0:
        return world.local_gear_table.pop()
    else:
        return ""


